// Independent ORIGINAL-position replay. No compressed types or SCC input.
// Catalogues are regenerated by restricted-growth strings, not loaded.
#include <algorithm>
#include <array>
#include <cassert>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using V=std::vector<int>; using Part=std::vector<V>;
std::vector<Part> local[7];
std::array<unsigned,8> table[7][7][2048];
bool crossing(const V&a,const V&b) {
  for(unsigned i=0;i<a.size();++i)for(unsigned k=i+1;k<a.size();++k) {
    int lo=std::min(a[i],a[k]),hi=std::max(a[i],a[k]),inside=0;
    for(int x:b)inside+=(lo<x&&x<hi);
    if(inside>0&&inside<(int)b.size())return true;
  }
  return false;
}
bool compatible(const Part&a,const Part&b) {
  for(auto&x:a)for(auto&y:b)if(crossing(x,y))return false;
  return true;
}
Part place(const Part&p,const V&g) {
  Part out;for(auto&b:p){V q;for(int x:b)q.push_back(g[x]);out.push_back(q);}return out;
}
void prepare() {
  for(int n:{5,6}) {
    V labels(n);
    auto rec=[&](auto&&self,int at,int count)->void {
      if(at==n) {
        Part p(count);for(int i=0;i<n;++i)p[labels[i]].push_back(i);
        for(auto&b:p)if(b.size()!=2&&b.size()!=3)return;
        for(int a=0;a<count;++a)for(int b=0;b<a;++b)if(crossing(p[a],p[b]))return;
        local[n].push_back(p);return;
      }
      for(int a=0;a<=count;++a){labels[at]=a;self(self,at+1,std::max(count,a+1));}
    };
    rec(rec,0,0);
  }
  assert(local[5].size()==5&&local[6].size()==8);
  for(int a:{5,6})for(int b:{5,6})if(a+b<=11)
    for(unsigned m=0;m<(1u<<(a+b));++m)if(__builtin_popcount(m)==a) {
      V x,y;for(int i=0;i<a+b;++i)((m>>i&1)?x:y).push_back(i);
      for(unsigned s=0;s<local[a].size();++s)for(unsigned t=0;t<local[b].size();++t)
        if(compatible(place(local[a][s],x),place(local[b][t],y)))table[a][b][m][s]|=1u<<t;
    }
}
int main(int argc,char**argv) {
  if(argc!=3)return 2;
  int j=std::stoi(argv[1]);if(j<2||j>9)return 2;
  std::ifstream f(argv[2]);if(!f)return 2;
  prepare();std::string line;std::uint64_t rows=0,nodes=0;std::map<V,std::uint64_t> shapes;
  while(std::getline(f,line)) {
    std::istringstream in(line);int k,type;in>>k>>type;assert((k==4||k==6)&&type>=0&&type<17);
    V p;int a;while(in>>a){assert(a>=0&&a<j);p.push_back(a);}assert(p.size()==(unsigned)(5*j+1));
    std::vector<V> gs(j);for(unsigned i=0;i<p.size();++i)gs[p[i]].push_back(i);
    assert(gs[0].size()==6);for(int a=1;a<j;++a)assert(gs[a].size()==5);
    std::vector<unsigned> reach(j);for(int a=0;a<j;++a){reach[a]=1u<<a;for(int b=0;b<j;++b)if(a!=b&&crossing(gs[a],gs[b]))reach[a]|=1u<<b;}
    for(int z=0;z<j;++z)for(int a=0;a<j;++a)if(reach[a]>>z&1)reach[a]|=reach[z];
    assert(reach[0]==(1u<<j)-1);
    std::vector<std::vector<std::array<unsigned,8>>> rel(j,std::vector<std::array<unsigned,8>>(j));
    for(int a=0;a<j;++a)for(int b=0;b<a;++b) {
      int na=gs[a].size(),nb=gs[b].size(),ia=0,ib=0;unsigned m=0;
      for(int i=0;i<na+nb;++i){if(ia<na&&(ib==nb||gs[a][ia]<gs[b][ib])){m|=1u<<i;++ia;}else ++ib;}
      rel[a][b]=table[na][nb][m];
      for(unsigned s=0;s<local[na].size();++s)for(unsigned t=0;t<local[nb].size();++t)if(rel[a][b][s]>>t&1)rel[b][a][t]|=1u<<s;
    }
    V assign(j,-1);std::vector<V> solutions;
    auto solve=[&](auto&&self,int depth)->void {
      ++nodes;if(depth==j){solutions.push_back(assign);assert(solutions.size()<=2);return;}
      int best=-1,size=9;unsigned domain=0;
      for(int a=0;a<j;++a)if(assign[a]<0) {
        unsigned d=(1u<<local[gs[a].size()].size())-1;
        for(int b=0;b<j;++b)if(assign[b]>=0)d&=rel[b][a][assign[b]];
        int z=__builtin_popcount(d);if(!z)return;if(z<size){best=a;size=z;domain=d;}
      }
      for(unsigned s=0;s<local[gs[best].size()].size();++s)if(domain>>s&1){assign[best]=s;self(self,depth+1);assign[best]=-1;}
    };
    solve(solve,0);assert(solutions.size()==2);
    for(int a=0;a<j;++a) {
      V parent(gs[a].size());for(unsigned i=0;i<parent.size();++i)parent[i]=i;
      auto root=[&](int x){while(parent[x]!=x)x=parent[x];return x;};
      for(auto&s:solutions)for(auto&b:local[gs[a].size()][s[a]])for(int x:b)parent[root(x)]=root(b[0]);
      for(unsigned x=0;x<parent.size();++x)assert(root(x)==root(0));
    }
    std::vector<V> runs(j);
    for(unsigned i=0;i<p.size();++i)if(p[i]!=p[(i+p.size()-1)%p.size()]) {
      int r=1;while(p[(i+r)%p.size()]==p[i])++r;runs[p[i]].push_back(r);
    }
    for(auto&r:runs)std::sort(r.begin(),r.end());
    for(int a=1;a<j;++a)assert(runs[a]==V({1,2,2}));
    ++shapes[runs[0]];++rows;
  }
  std::cout<<"{\"original_complete_family_replays\":"<<rows<<",\"csp_nodes\":"<<nodes<<",\"failures\":0,\"six_run_shapes\":[";
  bool first=true;for(auto&entry:shapes){if(!first)std::cout<<',';first=false;std::cout<<"{\"shape\":[";for(unsigned i=0;i<entry.first.size();++i)std::cout<<(i?",":"")<<entry.first[i];std::cout<<"],\"core_witnesses\":"<<entry.second<<"}";}
  std::cout<<"]}\n";
}
